    (forall q, live Aa q = live A q) ->
    (aroom Aa vma (kR - 0 * K1) (bR - 0 * B1)) ->
    (forall frb csb Ab Mb vmb rb cr dr,
       (W C Ab Mb (with_vmmaps vmb md)) ->
